from pathlib import Path
import json, hashlib, re, html
import markdown
from PIL import Image
R=Path(__file__).resolve().parents[4]
O=Path(__file__).resolve().parent
M=R/'commons/maps/Boolean_Colour_Spaces'
A=R/'commons/artifacts/boolean_colour_chamber'
S=R/'ada_run/boolean-colour-spaces-isolated'
runtime=json.loads((O/'runtime.json').read_text(encoding='utf-8'))
assert all(c['pass'] for c in runtime['checks'])
files=[]
for p in sorted(A.iterdir()):
 if p.suffix in ('.gd','.gdshader','.tscn'):
  assert p.read_bytes()==(S/p.relative_to(R)).read_bytes(),p
  files.append({'path':p.relative_to(R).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'matches_tested_copy':True})
for p in sorted(M.iterdir()):
 if p.is_file():files.append({'path':p.relative_to(R).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
p=R/'commons/artifacts/registry/boolean_colour_spaces.json'
reg=json.loads(p.read_text(encoding='utf-8'))
assert (R/reg['artifacts']['boolean_colour_chamber']['scene'].removeprefix('res://')).exists()
files.append({'path':p.relative_to(R).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
images=[]
for p in sorted(O.glob('*.png')):
 with Image.open(p) as im:
  im.load();assert im.size==(1440,900)
  images.append({'file':p.name,'size':list(im.size),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
assert len(images)==13
(O/'manifest.json').write_text(json.dumps({'scope':'Native production artifact in isolated desktop study; map data supplied but museum loader and headset untested.','runtime_checks':len(runtime['checks']),'source':files,'images':images},indent=2),encoding='utf-8')
body=markdown.markdown((M/'final.md').read_text(encoding='utf-8'))
body=re.sub(r'<h1>.*?</h1>','',body,count=1)
rooms=[('path','01','The path becomes a room','A box minus a union of spheres','Seven overlapping spherical cuts carry a route through the block. Two raised cuts let the ceiling depart from the path of the feet.','PEARL'),('lens','02','Only where they meet','A box minus the intersection of two spheres','The common region is removed. Round entrances and a light well connect this enclosed lens to the outside.','AMBER'),('shell','03','A shell with neighbours','An outer union, hollowed and perforated','Two joined bodies surround a connected interior. Different sizes of opening admit a walk, light, or a view.','CHROME')]
roomhtml=''
for name,n,title,formula,desc,finish in rooms:
 roomhtml+=f'<section class="room" id="{name}"><div class="roomhead"><span class="number">{n}</span><div><p class="eyebrow">{finish} / {name.upper()}</p><h2>{title}</h2><p>{desc}</p><p class="formula">{formula}</p></div></div><a href="{name}-inside.png"><img width="1440" height="900" loading="lazy" src="{name}-inside.png" alt="Native Godot interior of the {name} chamber"></a><details><summary>Entrance and ceiling views</summary><div class="pair"><figure><a href="{name}-entry.png"><img loading="lazy" src="{name}-entry.png" alt="{name} entrance"></a><figcaption>Approach from outside</figcaption></figure><figure><a href="{name}-ceiling.png"><img loading="lazy" src="{name}-ceiling.png" alt="{name} ceiling"></a><figcaption>Looking into the upper cuts</figcaption></figure></div></details></section>'
finishes=''.join(f'<figure><a href="surface-{i}.png"><img loading="lazy" src="surface-{i}.png" alt="Same path chamber in {name}"></a><figcaption><b>{name}</b> &mdash; {desc}</figcaption></figure>' for i,name,desc in [(0,'Pearl','pink and blue at the edge'),(1,'Amber','warm metallic light'),(2,'Chrome','dark reflection and pink seams'),(3,'Chalk','a quieter, matte comparison')])
page=r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cut a colour space | Ada Research</title><style>
:root{color-scheme:dark;--bg:#10121c;--text:#eee9ed;--muted:#b9b2c6;--line:#353243;--pink:#efbddc}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:17px/1.6 system-ui,sans-serif}a{color:var(--pink);text-underline-offset:.2em}header,main,footer{max-width:1160px;margin:auto;padding:32px}header{padding-top:68px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}h1{font:clamp(48px,7vw,92px)/1.04 Georgia,serif;letter-spacing:-.04em;margin:18px 0 28px;max-width:750px}h2{font:clamp(28px,4vw,44px)/1.15 Georgia,serif;letter-spacing:-.015em;margin:10px 0 22px}h3{font-size:19px}.lead{font:23px/1.55 Georgia,serif;max-width:760px}nav{display:flex;flex-wrap:wrap;gap:12px 26px;padding:22px 0}nav a{text-decoration:none;border-bottom:1px solid var(--line)}img{display:block;width:100%;height:auto;background:#191923;border-radius:4px}.hero{margin-top:30px}.caption,figcaption{font-size:14px;color:var(--muted);margin-top:10px}.intro{max-width:780px;margin:30px 0 72px}.room{border-top:1px solid var(--line);padding-top:40px;margin-bottom:80px;scroll-margin-top:24px}.roomhead{display:flex;gap:30px;max-width:850px;margin-bottom:26px}.number{font:36px/1.5 Georgia,serif;color:var(--pink)}.formula{color:var(--pink);font-size:14px}.pair,.finishes{display:grid;grid-template-columns:1fr 1fr;gap:22px}figure{margin:0}.finishes{margin:30px 0 72px}.finishes figcaption{margin-bottom:12px}details{margin:22px 0;border:1px solid var(--line);border-radius:4px;padding:16px 20px}summary{cursor:pointer;color:var(--pink)}details .pair{margin-top:24px}.play{background:#1b1b2b;padding:28px;border:1px solid var(--line);margin-bottom:64px}.play p{max-width:820px}code{font-size:14px;overflow-wrap:anywhere}.reading{max-width:770px;margin:0 auto 72px;font:21px/1.75 Georgia,serif}.reading h2{margin-top:54px}.reading p:has(img){margin:36px -50px 10px}.reading em{font-size:16px;color:var(--muted)}.evidence{font-size:15px;max-width:820px}footer{border-top:1px solid var(--line);color:var(--muted);font-size:13px;padding-bottom:60px}@media(max-width:680px){header,main,footer{padding:24px}header{padding-top:40px}.pair,.finishes{grid-template-columns:1fr}.roomhead{gap:15px}.reading p:has(img){margin-left:0;margin-right:0}.lead{font-size:21px}}
</style></head><body><header><p class="eyebrow">Ada Research / Boolean studies / 24 September 2026</p><h1>Cut a colour space.</h1><p class="lead">A line has passed through a volume and left more than a mark: it has left somewhere to go.</p><nav aria-label="Page sections"><a href="#path">Path</a><a href="#lens">Intersection</a><a href="#shell">Shell</a><a href="#finishes">Four finishes</a><a href="#play">Enter the study</a><a href="#reading">Read the hall</a></nav><a class="hero" href="path-inside.png"><img width="1440" height="900" src="path-inside.png" alt="Inside a pearl-coloured passage carved by overlapping spheres"></a><p class="caption">Native Godot capture of the working artifact. The chapter below uses these same images.</p></header><main><div class="intro"><p><a href="../2026-09-24-boolean-more-spaces/index.html">Continue to spaces 04–06: the loop, crossing vault and folded passage →</a></p><p>The reference images suggest spaces that hesitate between architecture, skin and machinery. This first study follows that tension through three different Boolean constructions, each large enough to enter.</p><p>Colour catches the cut. A rounded wall may appear soft, molten or metallic while its physical boundary remains firm. Changing the finish gives us another way to read the same space.</p></div>__ROOMS__<section id="finishes"><p class="eyebrow">One construction / four readings</p><h2>Change the skin. Keep the passage.</h2><p>These four captures hold the camera and geometry fixed. The entrance controls change the shader and local light colours. DRIFT slowly advances the pattern; press it again to hold the phase.</p><div class="finishes">__FINISHES__</div></section><section class="play" id="play"><p class="eyebrow">Playable desktop study</p><h2>Walk into the cuts.</h2><p>In Godot, open <code>commons/artifacts/boolean_colour_chamber/study.tscn</code> and run the scene with F6. Use WASD and mouse look; click the material buttons on each entrance plinth. Keys 1, 2 and 3 return to the corresponding entrances. Escape releases the mouse.</p><p>The three constructions are also placed in the new development map <code>Boolean_Colour_Spaces</code>. The scene above is the verified desktop entry point. The map is staged separately from the current three-hall Boolean spine, ready for a museum-loader and headset pass.</p><p><a href="/compose/sources?map=Boolean_Colour_Spaces&amp;doc=final">Open the study chapter in Sources</a> &middot; <a href="/boolean-space-gallery">Earlier Boolean space gallery</a></p></section><section id="reading" class="reading"><p class="eyebrow">Study chapter / current final.md</p>__READING__</section><section class="evidence"><h2>What has been checked</h2><p>A 1.8 m tall capsule with 0.30 m radius traversed each passage in both directions and stayed supported. Rays reached the entrance controls, standard pointer events selected all four finishes, and changing finishes preserved the generated geometry. The isolated run recorded 70 passing checks, including capture writes and mesh records.</p><p>The images are native Godot renders of the same production artifact. This is desktop evidence: headset experience, Quest performance and loading the new map through the full museum remain to be checked.</p><details><summary>Construction, sources and next experiments</summary><p>These are actual CSG cuts with collision, plus a separate level floor. The surfaces use procedural colour, metallic/roughness changes and view-dependent colour. They do not displace the wall or simulate physical thin-film optics.</p><p>The path study develops the mechanism found in the existing Random Boolean Carving family. The earlier architectural gallery and Radiolaria remain distinct sources for further work.</p><p>Useful next comparisons are a torus cut that makes a loop around a surviving core; ordered slab cuts meeting spherical cavities; and a Radiolaria-derived shell whose apertures admit different bodies. These are proposals, not additional built rooms.</p><p><a href="DECISIONS.md">Decisions and scope</a> &middot; <a href="runtime.json">Runtime results</a> &middot; <a href="manifest.json">Source and image hashes</a></p></details></section></main><footer>Ada Research &middot; Boolean Colour Spaces &middot; Same working artifact, museum study and book illustrations.</footer></body></html>"""
page=page.replace('__ROOMS__',roomhtml).replace('__FINISHES__',finishes).replace('__READING__',body)
(O/'index.html').write_text(page,encoding='utf-8')
print('Published',O/'index.html')
print('Verified',len(files),'source/map records and',len(images),'native images')
